/**
 * Compose SVG documents from the mark in `src/constants/brand-mark.ts`.
 *
 * Build-time only. The geometry deliberately lives in the app's constants rather than here
 * so the runtime component and the rendered icons cannot drift; this file just wraps it in
 * the grounds, masks and safe zones each platform wants.
 */

import {
  CHECK,
  GATE_PATHS,
  MARK_CANVAS,
  MARK_COLORS,
  NUKI,
} from "../src/constants/brand-mark.ts";

const GENERATED =
  "Generated by apps/mobile/scripts/generate-brand-assets.mjs — do not edit by hand.";

/**
 * The mark's ink, as SVG elements.
 *
 * Two tones by default rather than one, because iOS tinted mode maps luminance to a single
 * hue: cream reads near-white and amber reads mid, so the check stays distinguishable from
 * the gate instead of collapsing into a silhouette. Pass one colour for both when only
 * alpha survives, as in Android's themed icon.
 */
function markElements({ gate = MARK_COLORS.cream, check = MARK_COLORS.amber } = {}) {
  return [
    ...GATE_PATHS.map((d) => `<path d="${d}" fill="${gate}"/>`),
    `<rect x="${NUKI.x}" y="${NUKI.y}" width="${NUKI.width}" height="${NUKI.height}" rx="${NUKI.rx}" fill="${gate}"/>`,
    `<path d="${CHECK.d}" fill="none" stroke="${check}" stroke-width="${CHECK.strokeWidth}" stroke-linecap="round" stroke-linejoin="round"/>`,
  ].join("\n    ");
}

/**
 * An SVG document on the 1024 grid.
 *
 * `scale` shrinks the artwork about its centre, which is how the Android layers and the
 * maskable PWA icon get their safe zone without the geometry being restated at a second
 * size. `clipRadius` rounds the whole tile, for the one place nothing else masks it.
 */
export function svgDocument({
  background,
  scale = 1,
  clipRadius,
  comment = GENERATED,
  ink,
} = {}) {
  const offset = (MARK_CANVAS * (1 - scale)) / 2;
  const ground = background
    ? `<rect width="${MARK_CANVAS}" height="${MARK_CANVAS}" fill="${background}"/>`
    : "";

  const art =
    scale === 1
      ? markElements(ink)
      : `<g transform="translate(${offset} ${offset}) scale(${scale})">\n    ${markElements(ink)}\n    </g>`;

  const body = [ground, art].filter(Boolean).join("\n    ");

  const clipped = clipRadius
    ? `<clipPath id="tile"><rect width="${MARK_CANVAS}" height="${MARK_CANVAS}" rx="${clipRadius}" ry="${clipRadius}"/></clipPath>
  <g clip-path="url(#tile)">
    ${body}
  </g>`
    : body;

  return `<?xml version="1.0" encoding="UTF-8"?>
<!--
  ${comment}
-->
<svg xmlns="http://www.w3.org/2000/svg" width="${MARK_CANVAS}" height="${MARK_CANVAS}" viewBox="0 0 ${MARK_CANVAS} ${MARK_CANVAS}">
  ${clipped}
</svg>
`;
}

/** A flat ground, for the Android adaptive background layer. */
export function solidSquare(fill) {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!--
  ${GENERATED}
-->
<svg xmlns="http://www.w3.org/2000/svg" width="${MARK_CANVAS}" height="${MARK_CANVAS}" viewBox="0 0 ${MARK_CANVAS} ${MARK_CANVAS}">
  <rect width="${MARK_CANVAS}" height="${MARK_CANVAS}" fill="${fill}"/>
</svg>
`;
}
